from pathlib import Path
import json

data=Path.home()/".local/share/prediction-chat-bridge"
tid="DEV-PRED-CONT-CANARY2-A-20261003-E022"

def load(p):
    try:
        return json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        return None

hits={}
for name in ("outbox","inflight","sent"):
    found=[]
    d=data/name
    if d.is_dir():
        for p in d.glob("*.json"):
            o=load(p)
            if isinstance(o,dict) and o.get("task_id")==tid:
                found.append(p.name)
    hits[name]=found

if hits["sent"]:
    print("A_RESULT_LOCATION=SENT",flush=True)
    raise SystemExit(11)
if hits["inflight"]:
    print("A_RESULT_LOCATION=INFLIGHT",flush=True)
    raise SystemExit(12)
if hits["outbox"]:
    print("A_RESULT_LOCATION=OUTBOX",flush=True)
    raise SystemExit(13)
print("A_RESULT_LOCATION=MISSING",flush=True)
raise SystemExit(14)
